建一个空目录，把下面的最小基线和样例贴给本地 Agent。

import csv
import io
import sys
from pathlib import Path

def parse_csv(text):
    reader = csv.DictReader(io.StringIO(text))
    for column in ('sample_id', 'mae'):
        if column not in reader.fieldnames:
            raise ValueError(f'missing column: {column}')
    return list(reader)

if __name__ == '__main__':
    try:
        rows = parse_csv(Path(sys.argv[1]).read_text(encoding='utf-8'))
    except ValueError as error:
        print(error, file=sys.stderr)
        sys.exit(2)
    print(len(rows))

四个夹具为 normal.csv「sample_id,mae\nimg01,2\nimg02,3\n」、empty.csv（0 字节）、missing.csv「sample_id\nimg01\n」、header.csv「sample_id,mae\n」。字符串里的 \n 写成真正换行。
